const _ = require('lodash');
const constant = require('../lib/constant');

/**
 * string:
 * get key
 * incr key
 * incrby key increment
 * mget key [key ...]
 * mset key value [key value ...]
 * set key value
 * setex key value
 * setnx key value
 */
module.exports = (common) => {
  const operations = {
    * get(key, forceMaster) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key)) {
        return null;
      }
      return yield common.getValue(key, constant.TYPE.STRING, forceMaster);
    },

    * incr(key) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key)) {
        return false;
      }
      return yield operations.incrby(key, 1);
    },

    * incrby(key, increment) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key)) {
        return false;
      }
      increment = common.convertToInt(increment);
      for (let i = 0; i < common.retry; i++) {
        const objVer = yield common.getValueWithVer(key, constant.TYPE.STRING, constant.CONSTANT.FORCEMASTER);
        if (objVer === undefined) {
          return undefined;
        }
        let value;
        if (objVer.value === null) {
          value = increment.toString();
        } else {
          value = (common.convertToInt(objVer.value) + increment).toString();
        }
        const ret = yield common.setStringEx(key, common.toStringWithType(value, constant.TYPE.STRING), objVer.ver);
        if (ret === undefined) {
          return undefined;
        }
        if (ret) {
          return value;
        }
      }
      /* istanbul ignore next */
      return false;
    },

    * mget(...keys) {
      let forceMaster;
      if (keys.length > 1 && keys[keys.length - 1] === constant.CONSTANT.FORCEMASTER) {
        forceMaster = constant.CONSTANT.FORCEMASTER;
        keys = keys.slice(0, keys.length - 1);
      }
      keys = common.getFieldToArray(keys);
      /* istanbul ignore if */
      if (keys === null || keys.length === 0) {
        return [];
      }
      if (keys.length > 1) {
        return yield common.getBatch(keys, false, false, forceMaster);
      }
      const ret = yield operations.get(keys[0], forceMaster);
      if (ret === undefined) {
        return undefined;
      }
      return [ ret ];

    },

    * mset(...kvs) {
      let obj = common.getFieldToObj(kvs);
      if (obj === null) {
        return false;
      }
      obj = _.mapValues(obj, v => common.toStringWithType(v, constant.TYPE.STRING));
      return yield common.setBatchObj(obj);
    },

    * set(key, value) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || value === null || value === undefined) {
        return false;
      }
      return yield common.setString(key, common.toStringWithType(value, constant.TYPE.STRING));
    },

    * setnx(key, value) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || value === null || value === undefined) {
        return false;
      }
      return yield common.setStringEx(key, common.toStringWithType(value, constant.TYPE.STRING), 1);
    },

    * setex(key, value, seconds) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || value === null || value === undefined) {
        return false;
      }
      seconds = common.convertToInt(seconds);
      return yield common.setStringEx(key, common.toStringWithType(value, constant.TYPE.STRING), null, seconds, constant.CONSTANT.FORCEMASTER);
    },
  };
  return operations;
};
